//! The signer that room members use. The key pair is generated by the provider for whatever
//! scheme the room's suite calls for, and lives only in memory (and in the sealed state store).

use openmls_rust_crypto::RustCrypto;
use openmls_traits::crypto::OpenMlsCrypto;
use openmls_traits::signatures::{Signer, SignerError};
use openmls_traits::types::{CryptoError, SignatureScheme};

pub struct ProviderSigner {
    scheme: SignatureScheme,
    private: Vec<u8>,
    public: Vec<u8>,
}

impl ProviderSigner {
    /// New member key for `scheme`, which callers take from the room's suite.
    pub fn generate(backend: &RustCrypto, scheme: SignatureScheme) -> Result<Self, CryptoError> {
        let (private, public) = backend.signature_key_gen(scheme)?;
        Ok(Self {
            scheme,
            private,
            public,
        })
    }

    /// Restores a member key from the sealed state store.
    pub fn from_parts(scheme: SignatureScheme, private: Vec<u8>, public: Vec<u8>) -> Self {
        Self {
            scheme,
            private,
            public,
        }
    }

    pub fn public(&self) -> &[u8] {
        &self.public
    }

    pub fn scheme(&self) -> SignatureScheme {
        self.scheme
    }

    /// Private half, only for writing the sealed state file.
    pub fn private_bytes(&self) -> &[u8] {
        &self.private
    }
}

impl Signer for ProviderSigner {
    fn sign(&self, payload: &[u8]) -> Result<Vec<u8>, SignerError> {
        let backend = RustCrypto::default();
        backend
            .sign(self.scheme, payload, &self.private)
            .map_err(SignerError::CryptoError)
    }

    fn signature_scheme(&self) -> SignatureScheme {
        self.scheme
    }
}

impl std::fmt::Debug for ProviderSigner {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ProviderSigner")
            .field("scheme", &self.scheme)
            .finish_non_exhaustive()
    }
}
